    # TODO: with Timer() as t 结束后，t.elapsed 是耗时秒数
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False


with Timer() as t:
    pass
print(getattr(t, "elapsed", "没有 elapsed"))

class Guard:
    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return True


def risky():
    with Guard():
        raise ValueError("库存不能为负")


if __name__ == "__main__":
    risky()
    print("继续执行")

check.test:
try:
    risky()
    assert False, "异常被吞掉了"
except ValueError:
    pass
